 const createPO=()=>{if(!fullData.vendors?.length||!fullData.inventory?.length)return window.alert('Add a vendor and inventory item first.');const vendorId=window.prompt(`Vendor ID (${fullData.vendors.map(v=>v.id).join(', ')})`,fullData.vendors[0].id),itemId=window.prompt(`Part SKU (${fullData.inventory.map(i=>i.sku).join(', ')})`,fullData.inventory[0].sku),item=fullData.inventory.find(i=>i.sku===itemId||i.id===itemId);if(!vendorId||!item)return window.alert('Vendor or part was not found.');const quantity=Number(window.prompt('Quantity to order','1'));if(!Number.isInteger(quantity)||quantity<=0)return window.alert('Enter a whole quantity greater than zero.');save('purchaseOrders',{id:`PO-${Date.now().toString().slice(-6)}`,vendorId,locationId:activeLocationId||item.locationId||'',status:'Ordered',expected:new Date(Date.now()+7*864e5).toISOString().slice(0,10),total:Number(item.cost||0)*quantity,items:[{itemId:item.id,sku:item.sku,name:item.name,ordered:quantity,received:0,cost:Number(item.cost||0)}],createdAt:new Date().toISOString()});setTab('orders')}
 const draftLowStock=async()=>{const drafts=draftLowStockPurchaseOrders(fullData.inventory||[],fullData.purchaseOrders||[],activeLocationId);if(!drafts.length)return window.alert('No low-stock parts need purchase orders right now.');for(const po of drafts)await save('purchaseOrders',po);setTab('orders')}
 const receive=async(po:Row)=>{const line=po.items?.find((x:Row)=>Number(x.received||0)<Number(x.ordered||0));if(!line)return window.alert('This purchase order is fully received.');const item=stock.find(x=>x.id===line.itemId);if(!item)return window.alert('The inventory item no longer exists.');const remaining=Number(line.ordered)-Number(line.received||0),quantity=Number(window.prompt(`Receive quantity for ${item.name} (maximum ${remaining})`,String(remaining)));if(!Number.isInteger(quantity)||quantity<=0||quantity>remaining)return window.alert('Enter a valid receiving quantity.');await receiveInventory(String(po.id),String(line.itemId),quantity)}
 const transfer=(item:Row)=>{const destination=window.prompt('Transfer to bin/location',item.location||'');if(!destination?.trim()||destination===item.location)return;save('inventory',{...item,location:destination.trim()});save('inventoryTransactions',{id:`IT-${Date.now()}-${Math.random().toString(36).slice(2,5)}`,type:'Transfer',itemId:item.id,sku:item.sku,itemName:item.name,quantity:0,note:`${item.location||'Unassigned'} → ${destination.trim()}`,createdAt:new Date().toISOString(),fromLocation:item.location||'',toLocation:destination.trim()})}
 const returnPart=(item:Row)=>{const quantity=Number(window.prompt(`Quantity of ${item.name} to return`, '1'));if(!Number.isInteger(quantity)||quantity<=0||quantity>Number(item.onHand||0))return window.alert('Return quantity must be available in stock.');const reason=window.prompt('Return reason','Vendor return')||'Vendor return';save('inventory',{...item,onHand:Number(item.onHand)-quantity});save('inventoryTransactions',{id:`IT-${Date.now()}-${Math.random().toString(36).slice(2,5)}`,type:'Return',itemId:item.id,sku:item.sku,itemName:item.name,quantity:-quantity,note:reason,createdAt:new Date().toISOString()})}
 const countSheet:CountLine[]=stock.map(item=>({itemId:item.id,systemQty:Number(item.onHand||0),countedQty:Number(countLines[item.id]??item.onHand??0)})),variances=cycleCountVariances(countSheet)
